    static func districts(for city: String) -> [String] {
        if city == "全部" || city.isEmpty {
            return ["全部鄉鎮"]
        }
        let list = allStores.filter { $0.city == city }.map { $0.district }
        let unique = Array(Set(list)).filter { !$0.isEmpty }.sorted()
        return ["全部鄉鎮"] + unique
    }
